(966763, 114164, 17103, '<td valign="top">That is so sweet!  :)</td>', 'That is so sweet!  :)', '2004-10-20 12:04:37.000000', NULL, 1),
(966796, 113895, 27293, '<td valign="top">Very nice dynamic portrait. I think the square composition here kills the dynamics alittle, though. A horizontal shot would have been a lot more appealing to me. 8 and not a 10 because of that.</td>', 'Very nice dynamic portrait. I think the square composition here kills the dynamics alittle, though. A horizontal shot would have been a lot more appealing to me. 8 and not a 10 because of that.', '2004-10-20 12:47:38.000000', NULL, 1),
(966799, 113831, 26045, '<td valign="top">This is tops for me! One of the best compositions I''ve seen in this challenge, and good humor. 10</td>', 'This is tops for me! One of the best compositions I''ve seen in this challenge, and good humor. 10', '2004-10-20 12:49:13.000000', NULL, 1),
(966800, 113126, 26045, '<td valign="top">Excellent photo, composition, dof, but I''m still wishing that pen was really a pencil...regardless, I love it. Tops for me, 10.</td>', 'Excellent photo, composition, dof, but I''m still wishing that pen was really a pencil...regardless, I love it. Tops for me, 10.', '2004-10-20 12:50:00.000000', NULL, 1),
(966803, 113056, 27293, '<td valign="top">Very nice idea and subject, but i think it could have been presented much nicer.</td>', 'Very nice idea and subject, but i think it could have been presented much nicer.', '2004-10-20 12:51:05.000000', NULL, 1),
(966804, 114138, 26045, '<td valign="top">Love it, yes yes, very good idea! I don''t particularly care for the border (and no, I''m not one of those borderhaters)...it just distracts the tiniest bit. Love his expression, skewed glasses, all of it. Very nice in BW, too. 9 from me!</td>', 'Love it, yes yes, very good idea! I don''t particularly care for the border (and no, I''m not one of those borderhaters)...it just distracts the tiniest bit. Love his expression, skewed glasses, all of it. Very nice in BW, too. 9 from me!', '2004-10-20 12:51:20.000000', NULL, 1),
(966806, 114044, 26045, '<td valign="top">I love the idea, honestly, but the angle could''ve been better on this one. There is so much texture in the pages but I don''t think it was taken advantage of enough. Would''ve liked to see all dictionary, no background. Maybe an abstract shot, even. Regardless of all that, I give it a 9! Yay!</td>', 'I love the idea, honestly, but the angle could''ve been better on this one. There is so much texture in the pages but I don''t think it was taken advantage of enough. Would''ve liked to see all dictionary, no background. Maybe an abstract shot, even. Regardless of all that, I give it a 9! Yay!', '2004-10-20 12:52:42.000000', NULL, 1),
(966807, 114024, 9982, '<td valign="top">Love it. Very whimsical and charming. Good angle. Will probably score low on the DP Challenge though. 10</td>', 'Love it. Very whimsical and charming. Good angle. Will probably score low on the DP Challenge though. 10', '2004-10-20 12:52:49.000000', NULL, 1),
(966811, 114059, 26045, '<td valign="top">This is wonderful! I love it! 9</td>', 'This is wonderful! I love it! 9', '2004-10-20 12:58:53.000000', NULL, 1),
(966812, 113697, 26045, '<td valign="top">Oy, what style! I love it! 9</td>', 'Oy, what style! I love it! 9', '2004-10-20 12:59:48.000000', NULL, 1),
(966814, 113832, 26045, '<td valign="top">Very nice!! Tops for me! Is it my eyes, or is there a greenishness to the center of this photo? 9</td>', 'Very nice!! Tops for me! Is it my eyes, or is there a greenishness to the center of this photo? 9', '2004-10-20 13:00:45.000000', NULL, 1),
(966815, 114182, 26045, '<td valign="top">hahahaha very good idea, clever clever, well executed. 9</td>', 'hahahaha very good idea, clever clever, well executed. 9', '2004-10-20 13:01:15.000000', NULL, 1),
(966816, 114141, 26045, '<td valign="top">heh, his expression says it all. he looks like a rockstar in the works. 8</td>', 'heh, his expression says it all. he looks like a rockstar in the works. 8', '2004-10-20 13:01:56.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(966817, 114243, 26045, '<td valign="top">this is the best of the bus shots, imo. i love the autumn colors in the background, and the unique angle. 8</td>', 'this is the best of the bus shots, imo. i love the autumn colors in the background, and the unique angle. 8', '2004-10-20 13:02:33.000000', NULL, 1),
(966818, 114254, 26045, '<td valign="top">Wow, yaknow, this would''ve been the best of the bunch if it was in focus, cropped a bit better, had more detail. It''s such a good idea, kudos. 7</td>', 'Wow, yaknow, this would''ve been the best of the bunch if it was in focus, cropped a bit better, had more detail. It''s such a good idea, kudos. 7', '2004-10-20 13:03:33.000000', NULL, 1),
(966819, 114162, 26045, '<td valign="top">Beautiful shot, love that tree, great texture, love the lone leg, even the row of bikes, even the beautiful shadows, but the whole shot is crooked. And it would''ve been nice if you pulled back a touch to get the whole archway in the shot. Still, I like it very much. 7</td>', 'Beautiful shot, love that tree, great texture, love the lone leg, even the row of bikes, even the beautiful shadows, but the whole shot is crooked. And it would''ve been nice if you pulled back a touch to get the whole archway in the shot. Still, I like it very much. 7', '2004-10-20 13:04:37.000000', NULL, 1),
(966836, 113364, 16488, '<td valign="top">Ahh...the joy of accomplishment!  You''ve captured wonderful expresion in both subjects.  It seems difficult lighting made it hard for you to stop the motion entirely, which would have made this a near perfect image.</td>', 'Ahh...the joy of accomplishment!  You''ve captured wonderful expresion in both subjects.  It seems difficult lighting made it hard for you to stop the motion entirely, which would have made this a near perfect image.', '2004-10-20 13:34:15.000000', NULL, 1),
(966838, 114241, 16488, '<td valign="top">Yes, it''s a symbol of school--but I''m not sure it represents education very well.  Sky is blown out to ill effect.  Just wish there was something more here, something to tell a story.</td>', 'Yes, it''s a symbol of school--but I''m not sure it represents education very well.  Sky is blown out to ill effect.  Just wish there was something more here, something to tell a story.', '2004-10-20 13:36:08.000000', NULL, 1),
(966841, 114050, 772, '<td valign="top">Excellent perspective... I like the dynamics provided by the tilt of the camera.  It looks like you have been buried by the books :)</td>', 'Excellent perspective... I like the dynamics provided by the tilt of the camera.  It looks like you have been buried by the books :)', '2004-10-20 13:38:00.000000', NULL, 1),
(966842, 114016, 772, '<td valign="top">Beautifully exposed... the natural light in this shot is perfect... great work :)</td>', 'Beautifully exposed... the natural light in this shot is perfect... great work :)', '2004-10-20 13:38:49.000000', NULL, 1),
(966847, 114035, 27524, '<td valign="top">I like contrast of colors...good B&amp;W...nice compozition.</td>', 'I like contrast of colors...good B&W...nice compozition.', '2004-10-20 13:44:13.000000', NULL, 1),
(966852, 113879, 27524, '<td valign="top">Quality is good but object doesnt give much interest. Maybe B&amp;W would made it more artistic as there is good contrast of colors.</td>', 'Quality is good but object doesnt give much interest. Maybe B&W would made it more artistic as there is good contrast of colors.', '2004-10-20 13:46:29.000000', NULL, 1),
