(968458, 113907, 7322, '<td valign="top">This does meet the challenge but it does so in a very dull and literal way, IMO. This might be of some interest to the students at this school who care about sports and want to know the recent history of their team but there really isn''t anything here to attract an impartial viewer''s interest. The signs themselves are not striking in any way (to me, anyway) and most of the frame is taken up with the ugly institutional building.</td>', 'This does meet the challenge but it does so in a very dull and literal way, IMO. This might be of some interest to the students at this school who care about sports and want to know the recent history of their team but there really isn''t anything here to attract an impartial viewer''s interest. The signs themselves are not striking in any way (to me, anyway) and most of the frame is taken up with the ugly institutional building.', '2004-10-21 13:46:54.000000', NULL, 1),
(968460, 114158, 19010, '<td valign="top">looks like a good snap shot and part is out of focus.</td>', 'looks like a good snap shot and part is out of focus.', '2004-10-21 13:47:20.000000', NULL, 1),
