(969307, 114160, 14931, '<td valign="top">Captures a mood I remember well.  The lines and subdued light bring just the right feel to this moment...</td>', 'Captures a mood I remember well.  The lines and subdued light bring just the right feel to this moment...', '2004-10-22 00:34:08.000000', NULL, 1),
(969310, 114059, 14931, '<td valign="top">very sweet, and I remember many school moments like this.  While not the most technically well done photo, brings back happier memories than most in this challenge.</td>', 'very sweet, and I remember many school moments like this.  While not the most technically well done photo, brings back happier memories than most in this challenge.', '2004-10-22 00:35:36.000000', NULL, 1),
(969313, 114072, 14931, '<td valign="top">Really show''s a "love" of learning.  Clever and insightful.  One of the best I''ve seen in this challenge.</td>', 'Really show''s a "love" of learning.  Clever and insightful.  One of the best I''ve seen in this challenge.', '2004-10-22 00:36:44.000000', NULL, 1),
(969314, 114254, 14931, '<td valign="top">very cool.  Not sure a book by itself indicates school, but at least it''s an origional take on the subject.</td>', 'very cool.  Not sure a book by itself indicates school, but at least it''s an origional take on the subject.', '2004-10-22 00:37:39.000000', NULL, 1),
(969315, 114187, 14931, '<td valign="top">Kind of bland photograph, but it does convey the subject.</td>', 'Kind of bland photograph, but it does convey the subject.', '2004-10-22 00:38:17.000000', NULL, 1),
