(969319, 113212, 14931, '<td valign="top">very desolate.  Makes me wonder where you went to school.</td>', 'very desolate.  Makes me wonder where you went to school.', '2004-10-22 00:40:39.000000', NULL, 1),
(969320, 113308, 14931, '<td valign="top">I remember the feeling you''re going for, but I don''t care for the composition in this picture.  The cropping feels wrong, just a bit too tight.</td>', 'I remember the feeling you''re going for, but I don''t care for the composition in this picture.  The cropping feels wrong, just a bit too tight.', '2004-10-22 00:42:14.000000', NULL, 1),
(969323, 113784, 14931, '<td valign="top">Just not a strong photo for the challenge.  It''s too close to the board it seems, and the lighting looks unbalanced, too dark for the top and bottom, and too washed out in the center from the reflection.</td>', 'Just not a strong photo for the challenge.  It''s too close to the board it seems, and the lighting looks unbalanced, too dark for the top and bottom, and too washed out in the center from the reflection.', '2004-10-22 00:44:16.000000', NULL, 1),
(969324, 113471, 14931, '<td valign="top">intersting colors, but not something I would think school memories are made of.</td>', 'intersting colors, but not something I would think school memories are made of.', '2004-10-22 00:45:19.000000', NULL, 1),
(969325, 114161, 14931, '<td valign="top">Hit''s the mark right on.  Color balance it a bit dull though.</td>', 'Hit''s the mark right on.  Color balance it a bit dull though.', '2004-10-22 00:45:55.000000', NULL, 1),
(969326, 114125, 14931, '<td valign="top">it''s ok, just doesn''t seem to convey much in the way of actual school memories.  The angles of the foreground and background do not match up; neither parallel or complimentary.</td>', 'it''s ok, just doesn''t seem to convey much in the way of actual school memories.  The angles of the foreground and background do not match up; neither parallel or complimentary.', '2004-10-22 00:48:09.000000', NULL, 1),
(969336, 114197, 21069, '<td valign="top">Nice photo - but i must add , this room goes against the rules of ergonomics, the head should be inline with the monitor at eye level, Im giving you a [7] but i think you should get the school people to fix the problem<br/>(will give the student a sore neck and bad posture) <br/> <br/>The main reason for a 7 and not an 8 is because although itz modern day school, itz not really old school as i interpret the challenge to be based on but other than that nice colour and detail and should fair well</td>', 'Nice photo - but i must add , this room goes against the rules of ergonomics, the head should be inline with the monitor at eye level, Im giving you a [7] but i think you should get the school people to fix the problem(will give the student a sore neck and bad posture)  The main reason for a 7 and not an 8 is because although itz modern day school, itz not really old school as i interpret the challenge to be based on but other than that nice colour and detail and should fair well', '2004-10-22 01:00:19.000000', NULL, 1),
(969337, 112914, 21069, '<td valign="top">your title is too confusing /"complicated" :p</td>', 'your title is too confusing /"complicated" :p', '2004-10-22 01:01:58.000000', NULL, 1),
(969340, 112590, 21069, '<td valign="top">too bright probally something to do with the on board flash - maybe next time take advantage of natural lighting and use a tripod to reduce blurriess which occurs when not using the flash - also the surface is very reflective and the eyes tend to focus on the bottom right of the picture - sorry but hope you learn from your mistake</td>', 'too bright probally something to do with the on board flash - maybe next time take advantage of natural lighting and use a tripod to reduce blurriess which occurs when not using the flash - also the surface is very reflective and the eyes tend to focus on the bottom right of the picture - sorry but hope you learn from your mistake', '2004-10-22 01:05:06.000000', NULL, 1),
(969344, 114028, 19445, '<td valign="top">the dutch angle seems to confuse more than add to the pic</td>', 'the dutch angle seems to confuse more than add to the pic', '2004-10-22 01:07:54.000000', NULL, 1),
