(969789, 113351, 24925, '<td valign="top">This is okay, and I like the faded effect.  It seems the red apple should have been either more or less colourful.  It doesn''t look quite colourful enough to be the main focus of my attention, but not quite faded enough to blend in with the rest of the photo.  The same applies to the tips of the four pens/markers...my vote would be to make the colours more vibrant.</td>', 'This is okay, and I like the faded effect.  It seems the red apple should have been either more or less colourful.  It doesn''t look quite colourful enough to be the main focus of my attention, but not quite faded enough to blend in with the rest of the photo.  The same applies to the tips of the four pens/markers...my vote would be to make the colours more vibrant.', '2004-10-22 13:59:25.000000', NULL, 1),
(969791, 112614, 24925, '<td valign="top">Spooky-like...but not quite enough.  I can''t tell if you''re going for warm and comfortable or spooky and cold...One way or the other would be great, but the amibiguity makes this photo less enjoyable.  I think another edit of this would make for a great photo, though!</td>', 'Spooky-like...but not quite enough.  I can''t tell if you''re going for warm and comfortable or spooky and cold...One way or the other would be great, but the amibiguity makes this photo less enjoyable.  I think another edit of this would make for a great photo, though!', '2004-10-22 14:01:02.000000', NULL, 1),
(969792, 113070, 24925, '<td valign="top">Cute, but weird...not incredibly appealing and doesn''t capture my gaze for too long.  Nice colours, though...</td>', 'Cute, but weird...not incredibly appealing and doesn''t capture my gaze for too long.  Nice colours, though...', '2004-10-22 14:01:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(969794, 112621, 24925, '<td valign="top">This seems too simplistic and stale to me...The focus and lighting are kind of blah and the composition seems slightly tilted.</td>', 'This seems too simplistic and stale to me...The focus and lighting are kind of blah and the composition seems slightly tilted.', '2004-10-22 14:03:17.000000', NULL, 1),
(969795, 114160, 16488, '<td valign="top">Clever title and the idea of capturing the shadow on the building is great.  I think this could be improved by leveling the horizon line and using a tighter crop to focus attention more closely on your subject.</td>', 'Clever title and the idea of capturing the shadow on the building is great.  I think this could be improved by leveling the horizon line and using a tighter crop to focus attention more closely on your subject.', '2004-10-22 14:03:56.000000', NULL, 1),
(969797, 113048, 24925, '<td valign="top">I feel too far removed from this photo...Had you gotten closer and on the same level, capturing the children''s astonished and amused faces with the bear in the background I would have really enjoyed this photo.  You have captured a great moment, but have left a lot unsaid in this photo.  Next time an opportunity like this comes along, be bold and capture that photograph you really wanted...</td>', 'I feel too far removed from this photo...Had you gotten closer and on the same level, capturing the children''s astonished and amused faces with the bear in the background I would have really enjoyed this photo.  You have captured a great moment, but have left a lot unsaid in this photo.  Next time an opportunity like this comes along, be bold and capture that photograph you really wanted...', '2004-10-22 14:05:41.000000', NULL, 1),
(969798, 113834, 24925, '<td valign="top">5.  This photo seems a little too obvious for my taste...that being said, it''s well done.</td>', '5.  This photo seems a little too obvious for my taste...that being said, it''s well done.', '2004-10-22 14:06:33.000000', NULL, 1),
(969802, 113923, 16488, '<td valign="top">I think I get it--Jonathan Livingston Pigeon!  Cute idea.<br/> <br/>Composition is effective.  Colors are nice--orange/blue works well.  It would have been even nicer if that scene-stealer hadn''t imposed itself in the bottom right of the picture.  Saved somewhat by the building as background...but didn''t you just wish you could  clone it out?</td>', 'I think I get it--Jonathan Livingston Pigeon!  Cute idea. Composition is effective.  Colors are nice--orange/blue works well.  It would have been even nicer if that scene-stealer hadn''t imposed itself in the bottom right of the picture.  Saved somewhat by the building as background...but didn''t you just wish you could  clone it out?', '2004-10-22 14:07:40.000000', NULL, 1),
(969803, 113400, 24925, '<td valign="top">The problem with taking photos of your pet is that you have a relationship with your dog, I don''t.  I''m removed from this photo and it doesn''t really speak to me like it does to you.  I''m sure you like this photo, and you should!  It''s cute!  That being said, it does very little for me, sorry...</td>', 'The problem with taking photos of your pet is that you have a relationship with your dog, I don''t.  I''m removed from this photo and it doesn''t really speak to me like it does to you.  I''m sure you like this photo, and you should!  It''s cute!  That being said, it does very little for me, sorry...', '2004-10-22 14:07:57.000000', NULL, 1),
(969805, 113831, 10988, '<td valign="top">WOW...that''s great!  I love the idea and the execution</td>', 'WOW...that''s great!  I love the idea and the execution', '2004-10-22 14:09:18.000000', NULL, 1),
(969806, 114096, 10988, '<td valign="top">Good solid shot</td>', 'Good solid shot', '2004-10-22 14:10:34.000000', NULL, 1),
(969808, 114242, 10988, '<td valign="top">Very nice</td>', 'Very nice', '2004-10-22 14:11:07.000000', NULL, 1),
(969810, 113766, 10988, '<td valign="top">nice shot, I like the B&amp;W</td>', 'nice shot, I like the B&W', '2004-10-22 14:12:53.000000', NULL, 1),
(969811, 112899, 10988, '<td valign="top">Nice picture</td>', 'Nice picture', '2004-10-22 14:13:53.000000', NULL, 1),
(969817, 114242, 3102, '<td valign="top">Really cool vantage point on this one -- well done!  My only nitpick is that I''m not sure whether the chair adds to the shot.  This is one of my favorites this time around.</td>', 'Really cool vantage point on this one -- well done!  My only nitpick is that I''m not sure whether the chair adds to the shot.  This is one of my favorites this time around.', '2004-10-22 14:22:24.000000', NULL, 1),
(969818, 113048, 27244, '<td valign="top">Hey! My teachers did not let us sit on the rails...  Fun image.</td>', 'Hey! My teachers did not let us sit on the rails...  Fun image.', '2004-10-22 14:22:28.000000', NULL, 1),
(969822, 114164, 27244, '<td valign="top">Cute little cheerleader!</td>', 'Cute little cheerleader!', '2004-10-22 14:24:51.000000', NULL, 1),
(969823, 114016, 3102, '<td valign="top">Very nicely done!  I like the simplicity here.  The use of black &amp; white is great, and the lighting is really well done.  Some folks will probably say that they would have eliminated the little girl in the background, but I think it really adds to the shot.  Having her playing joyfully in the background, to me, helps to tell a story of a girl who is determined to get her homework done despite the temptations of having fun instead.  My only 10 of the challenge.</td>', 'Very nicely done!  I like the simplicity here.  The use of black & white is great, and the lighting is really well done.  Some folks will probably say that they would have eliminated the little girl in the background, but I think it really adds to the shot.  Having her playing joyfully in the background, to me, helps to tell a story of a girl who is determined to get her homework done despite the temptations of having fun instead.  My only 10 of the challenge.', '2004-10-22 14:25:28.000000', NULL, 1),
(969824, 114059, 3102, '<td valign="top">Very cute shot -- they''re quite a photogenic bunch!  One of my favorites this time around.</td>', 'Very cute shot -- they''re quite a photogenic bunch!  One of my favorites this time around.', '2004-10-22 14:26:01.000000', NULL, 1),
(969826, 114152, 3102, '<td valign="top">Seems a bit cluttered to me, and the colors are way too blue-ish.</td>', 'Seems a bit cluttered to me, and the colors are way too blue-ish.', '2004-10-22 14:26:41.000000', NULL, 1),
(969827, 113895, 27244, '<td valign="top">My least favorite subject :)  Good composition and lighting.  (7)</td>', 'My least favorite subject :)  Good composition and lighting.  (7)', '2004-10-22 14:27:09.000000', NULL, 1),
(969828, 114024, 3102, '<td valign="top">I''m afraid this seems just a bit too haphazard.  It honestly doesn''t look like a lot of effort was put into framing, lighting or focus here.  Sorry...</td>', 'I''m afraid this seems just a bit too haphazard.  It honestly doesn''t look like a lot of effort was put into framing, lighting or focus here.  Sorry...', '2004-10-22 14:27:33.000000', NULL, 1),
(969830, 113895, 3102, '<td valign="top">There''s nothing tremendously exciting or "WOW" about it, but I still like this shot a lot.  It''s very simple, yet conveys an expression of someone who is passionate about teaching.  I gave ''er an 8.</td>', 'There''s nothing tremendously exciting or "WOW" about it, but I still like this shot a lot.  It''s very simple, yet conveys an expression of someone who is passionate about teaching.  I gave ''er an 8.', '2004-10-22 14:29:18.000000', NULL, 1),
(969831, 114123, 27244, '<td valign="top">Not getting what this has to do with school days...  Is there some sort of hidden meaning? Otherwise good composition.</td>', 'Not getting what this has to do with school days...  Is there some sort of hidden meaning? Otherwise good composition.', '2004-10-22 14:29:50.000000', NULL, 1),
(969833, 113895, 24925, '<td valign="top">I kind of like this one...I''m not sure if it''s on purpose or not (because it has the qualities of a snapshot), but it really makes me feel like I''m back in school.  It has that personal impersonality to it, it''s a tad cold, it almost immediately bores me.  I am giving this a 5 because for the type of photo that it is, it''s pretty good...</td>', 'I kind of like this one...I''m not sure if it''s on purpose or not (because it has the qualities of a snapshot), but it really makes me feel like I''m back in school.  It has that personal impersonality to it, it''s a tad cold, it almost immediately bores me.  I am giving this a 5 because for the type of photo that it is, it''s pretty good...', '2004-10-22 14:30:23.000000', NULL, 1),
(969836, 114187, 24925, '<td valign="top">Decent candid...distracting elements take away from the viewability of the photo, but overall not too bad...</td>', 'Decent candid...distracting elements take away from the viewability of the photo, but overall not too bad...', '2004-10-22 14:31:23.000000', NULL, 1),
(969837, 113766, 3102, '<td valign="top">I was surprised there weren''t more high school football shots in here!  I think you caught the action quite nicely here, and black &amp; white gives it a yearbook-ish feel to it.  There are some spots in this shot that would have been better if they could have been dodged/burned a bit, but that ain''t legal for this one!  I think you did a good job considering the editing restrictions here.</td>', 'I was surprised there weren''t more high school football shots in here!  I think you caught the action quite nicely here, and black & white gives it a yearbook-ish feel to it.  There are some spots in this shot that would have been better if they could have been dodged/burned a bit, but that ain''t legal for this one!  I think you did a good job considering the editing restrictions here.', '2004-10-22 14:31:32.000000', NULL, 1),
(969839, 112947, 3102, '<td valign="top">Very cute shot!  I think it could use just a little more contrast, but I like the subjects and the composition quite well!</td>', 'Very cute shot!  I think it could use just a little more contrast, but I like the subjects and the composition quite well!', '2004-10-22 14:32:41.000000', NULL, 1),
(969841, 112872, 27244, '<td valign="top">Good take on the subject!  The B&amp;W seems to gray and you also get a glare off the book which distracts the eye.  Also the models hand is not sitting very natural upon the book.</td>', 'Good take on the subject!  The B&W seems to gray and you also get a glare off the book which distracts the eye.  Also the models hand is not sitting very natural upon the book.', '2004-10-22 14:33:07.000000', NULL, 1),
(969844, 113710, 27244, '<td valign="top">Did they take your lunch money too?  Fun take on the school bully''s.  The guy in blue does not look so mean though.   Giving you a 6</td>', 'Did they take your lunch money too?  Fun take on the school bully''s.  The guy in blue does not look so mean though.   Giving you a 6', '2004-10-22 14:34:54.000000', NULL, 1),
(969845, 114048, 27244, '<td valign="top">Fun, Fun, Fun!  Nice take on the apple.  The set up is nice, DOF is great.  Giving you a 7</td>', 'Fun, Fun, Fun!  Nice take on the apple.  The set up is nice, DOF is great.  Giving you a 7', '2004-10-22 14:36:37.000000', NULL, 1),
(969847, 113400, 27244, '<td valign="top">:)</td>', ':)', '2004-10-22 14:38:22.000000', NULL, 1),
(969848, 114029, 3102, '<td valign="top">A neat idea/vantage point... although I would have tried to use something completely white on the right side so the "Epson" mark doesn''t show up like that.  Perhaps a different crop could have eliminated that.</td>', 'A neat idea/vantage point... although I would have tried to use something completely white on the right side so the "Epson" mark doesn''t show up like that.  Perhaps a different crop could have eliminated that.', '2004-10-22 14:38:34.000000', NULL, 1),
