INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(973208, 113852, 25218, '<td valign="top">nice swirl of color!</td>', 'nice swirl of color!', '2004-10-25 16:16:47.000000', NULL, 1),
(973218, 113227, 16493, '<td valign="top">The ugly photographer..</td>', 'The ugly photographer..', '2004-10-25 16:24:13.000000', NULL, 1),
(973256, 114072, 28463, '<td valign="top">good execution, but 0 on originality, ive seen this done 1000 times</td>', 'good execution, but 0 on originality, ive seen this done 1000 times', '2004-10-25 16:57:17.000000', NULL, 1),
(973273, 114024, 28463, '<td valign="top">did the camera go off unexpectedly on this shot?  Whats the focus of this shot?  Is it the coats?  the hooks? the cubby holes? I have no idea.  Your depth of field is also very small.  once you get past the first or second coat, everything is out of focus.  When youre shooting a shot like this, compose it in your viewfinder to see if you can cut out anything thats distracting.  Lets say you wanted the coats to be your focus... now you have this huge spot in the top right thats distracting the subject.  Get rid of it.  Also, its obvious you used a flash, due to the light boards in the top left and the reflection on the coats.  Try not to use the flash in this situation... <br/></td>', 'did the camera go off unexpectedly on this shot?  Whats the focus of this shot?  Is it the coats?  the hooks? the cubby holes? I have no idea.  Your depth of field is also very small.  once you get past the first or second coat, everything is out of focus.  When youre shooting a shot like this, compose it in your viewfinder to see if you can cut out anything thats distracting.  Lets say you wanted the coats to be your focus... now you have this huge spot in the top right thats distracting the subject.  Get rid of it.  Also, its obvious you used a flash, due to the light boards in the top left and the reflection on the coats.  Try not to use the flash in this situation... ', '2004-10-25 17:07:25.000000', NULL, 1),
(973291, 113593, 25508, '<td valign="top">great photo</td>', 'great photo', '2004-10-25 17:19:11.000000', NULL, 1),
(973340, 114243, 20836, '<td valign="top">great photo. congratulations</td>', 'great photo. congratulations', '2004-10-25 17:57:05.000000', NULL, 1),
